/* ---------- Firestore helpers (drop-in replacements for the old
   window.storage-based sGet/sSet/sDelete, same call shape) ----------
   Collection layout:
     matches/{matchId}              - live game state (shared, both players)
     matchmakingQueue/{uid}         - one doc per waiting player
     users/{uid}/decks/{hero}       - a player's saved custom deck for a hero
     users/{uid}                    - profile (display name, win/loss, tier)
   "shared" from the old API doesn't map directly to Firestore's model
   (everything is a real document with its own rules), so these helpers
   take an explicit Firestore path instead. */
async function fGet(path) {
  try {
    const snap = await getDoc(doc(db, ...path));
    return snap.exists() ? snap.data() : null;
  } catch (e) {
    console.error("fGet failed:", path, e);
    return null;
  }
}
async function fSet(path, value, retries = 2) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      await setDoc(doc(db, ...path), value);
      return true;
    } catch (e) {
      if (attempt < retries) await new Promise((res) => setTimeout(res, 400 * (attempt + 1)));
    }
  }
  return false;
}
async function fDelete(path) {
  try {
    await deleteDoc(doc(db, ...path));
  } catch (e) {}
}

/* ---------- utility ---------- */
let _uidCounter = 0;
function uid() {
  _uidCounter += 1;
  return Math.random().toString(36).slice(2) + Date.now().toString(36) + "_" + _uidCounter;
}
function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
function hash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) | 0;
  return Math.abs(h);
}

