function CardIcon({ name, size = 34 }) {
  const keys = Object.keys(ICON_PATHS);
  const key = keys[hash(name) % keys.length];
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} style={{ opacity: 0.85 }}>
      <path d={ICON_PATHS[key]} fill="none" stroke="#111" strokeWidth="1.1" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

