function textureCanvas(canvas, seed, iconKey) {
  const ctx = canvas.getContext("2d");
  const S = canvas.width;
  const rnd = (n) => { const x = Math.sin(seed + n) * 10000; return x - Math.floor(x); };

  // base grey tone, varies slightly per card
  const base = 150 + Math.floor(rnd(1) * 60);
  ctx.fillStyle = `rgb(${base},${base},${base})`;
  ctx.fillRect(0, 0, S, S);

  // grain
  for (let i = 0; i < 260; i++) {
    const x = rnd(i * 3 + 2) * S, y = rnd(i * 3 + 3) * S;
    const shade = Math.floor(rnd(i * 3 + 4) * 255);
    ctx.fillStyle = `rgba(${shade},${shade},${shade},0.10)`;
    ctx.fillRect(x, y, 1.6, 1.6);
  }

  // vignette
  const grad = ctx.createRadialGradient(S / 2, S / 2, S * 0.2, S / 2, S / 2, S * 0.7);
  grad.addColorStop(0, "rgba(0,0,0,0)");
  grad.addColorStop(1, "rgba(0,0,0,0.55)");
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, S, S);

  // subject silhouette (reuse existing icon path)
  ctx.save();
  ctx.translate(S * 0.15, S * 0.15);
  ctx.scale((S * 0.7) / 24, (S * 0.7) / 24);
  ctx.strokeStyle = "rgba(20,20,20,0.9)";
  ctx.lineWidth = 1.4;
  ctx.lineJoin = "round";
  ctx.lineCap = "round";
  try { ctx.stroke(new Path2D(ICON_PATHS[iconKey])); } catch (e) {}
  ctx.restore();

  // torn paper border
  ctx.strokeStyle = "rgba(0,0,0,0.35)";
  ctx.lineWidth = 2;
  ctx.strokeRect(1, 1, S - 2, S - 2);
}

function CardArt({ card, size = 34 }) {
  const canvasRef = useRef(null);
  const override = CARD_ART_OVERRIDES[card.name];
  useEffect(() => {
    if (override || !canvasRef.current) return;
    const keys = Object.keys(ICON_PATHS);
    const iconKey = keys[hash(card.name) % keys.length];
    textureCanvas(canvasRef.current, hash(card.id || card.name), iconKey);
  }, [card.name, card.id, override]);

  if (override) {
    return <img src={override} alt={card.name} style={{ width: size, height: size, objectFit: "cover", filter: "grayscale(100%)", border: "1px solid #ccc", borderRadius: 3 }} />;
  }
  return <canvas ref={canvasRef} width={90} height={90} style={{ width: size, height: size, borderRadius: 3, imageRendering: "auto" }} />;
}

