function statsFor(cost, tier) {
  const bonus = tier === "rare" ? 1 : tier === "epic" ? 2 : tier === "unique" ? 3 : 0;
  const base = cost * 2 + bonus;
  const atk = Math.max(1, Math.round(base * 0.45));
  const hp = Math.max(1, base - atk);
  return { atk, hp };
}

