function pushCard(db, c, rarity, hero, copies) {
  db.push({
    id: nextId(), name: c.name, cost: c.cost, type: c.type || "minion",
    atk: c.atk ?? null, hp: c.hp ?? null, rarity, hero,
    keywords: c.keywords || [], text: c.text || "",
    effect: c.effect || null, deathrattle: c.deathrattle || null,
    onDamage: c.onDamage || null, needsTarget: c.needsTarget || null,
    onTurnStart: c.onTurnStart || null, onAttack: c.onAttack || null,
    copies,
  });
}

function buildDatabase() {
  const db = [];

  // --- faction (hero) cards, hand authored ---
  HEROES.forEach((hero) => {
    const set = HERO_CARDS[hero];
    set.common.forEach((c) => pushCard(db, c, "common", hero, 2));
    set.rare.forEach((c) => pushCard(db, c, "rare", hero, 2));
    set.epic.forEach((c) => pushCard(db, c, "epic", hero, 2));
    pushCard(db, set.unique, "unique", hero, 1);
  });

  // --- neutral cards, hand authored ---
  NEUTRAL_CARDS.common.forEach((c) => pushCard(db, c, "common", null, 2));
  NEUTRAL_CARDS.rare.forEach((c) => pushCard(db, c, "rare", null, 2));
  NEUTRAL_CARDS.epic.forEach((c) => pushCard(db, c, "epic", null, 2));
  NEUTRAL_CARDS.unique.forEach((c) => pushCard(db, c, "unique", null, 1));

  return db;
}

const CARD_DB = buildDatabase();
const TOKENS = {
  Radroach: { name: "Radroach", atk: 1, hp: 1, keywords: [], text: "" },
  Raider: { name: "Raider", atk: 2, hp: 2, keywords: [], text: "" },
};

function findCard(id) { return CARD_DB.find((c) => c.id === id); }
function findCardByName(name) { return CARD_DB.find((c) => c.name === name); }

/* ---------- preset 30-card decks ---------- */
const NEUTRAL_COMMON_DEFS = CARD_DB.filter((c) => c.rarity === "common" && !c.hero);
const NEUTRAL_UNIQUE_DEFS = CARD_DB.filter((c) => c.rarity === "unique" && !c.hero);

function buildDeckFor(hero) {
  const heroIdx = HEROES.indexOf(hero);
  const slotIdx = heroIdx % NEUTRAL_UNIQUE_DEFS.length; // cycles safely if hero count ever exceeds the neutral unique pool
  const heroCards = CARD_DB.filter((c) => c.hero === hero);
  const deck = [];
  heroCards.forEach((c) => { for (let i = 0; i < c.copies; i++) deck.push(c.id); });
  const fillerCommons = NEUTRAL_COMMON_DEFS.slice(slotIdx * 5, slotIdx * 5 + 4);
  fillerCommons.forEach((c) => { deck.push(c.id); deck.push(c.id); });
  const signatureUnique = NEUTRAL_UNIQUE_DEFS[slotIdx];
  deck.push(signatureUnique.id);
  return deck;
}

// Checks a deck (array of card ids) is legal for the given hero:
// exactly 30 cards, every id is a real card, every card belongs to this
// hero or is neutral, and no card exceeds its allowed copy count.
function validateDeck(deck, hero) {
  if (!Array.isArray(deck) || deck.length !== 30) return false;
  const counts = {};
  for (const id of deck) {
    const card = findCard(id);
    if (!card) return false;
    if (card.hero && card.hero !== hero) return false;
    counts[id] = (counts[id] || 0) + 1;
    if (counts[id] > card.copies) return false;
  }
  return true;
}

const HERO_POWERS = {
  Wanderer: { name: "Explore", desc: "Draw a card.", cost: 2, needsTarget: null },
  Prepper: { name: "Fortify", desc: "Gain 2 Armor.", cost: 2, needsTarget: null },
  Mutant: { name: "Mutate", desc: "Give a friendly minion +1/+1.", cost: 2, needsTarget: "friendlyMinion" },
  Scientist: { name: "Experiment", desc: "Deal 1 damage to any target.", cost: 2, needsTarget: "any" },
  Bandit: { name: "Mug", desc: "Deal 2 damage to enemy hero.", cost: 2, needsTarget: null },
  Cyborg: { name: "Repair", desc: "Restore 1 Health and gain 1 Armor.", cost: 2, needsTarget: null },
};

/* =========================================================================
   GAME ENGINE (pure-ish functions operating on a plain state object)
   ========================================================================= */
function freshPlayer(sessionId, hero, goingFirst, customDeck, displayName) {
  const baseDeck = validateDeck(customDeck, hero) ? customDeck : buildDeckFor(hero);
  const deckIds = shuffle(baseDeck);
  const handCount = goingFirst ? 3 : 4;
  const hand = deckIds.splice(0, handCount);
  return {
    sessionId, hero, displayName: displayName || "", health: 30, maxHealth: 30, armor: 0,
    mana: 0, maxMana: 0, deck: deckIds, hand, board: [],
    powerUsed: false, fatigue: 0,
  };
}

function makeMinionInstance(cardId, canAttack) {
  const c = findCard(cardId);
  return {
    uid: uid(), cardId, name: c.name, atk: c.atk, hp: c.hp, maxHp: c.hp,
    keywords: [...c.keywords], canAttack: !!canAttack, shielded: c.keywords.includes("Reinforced"),
    frozen: false, onDamage: c.onDamage || null,
  };
}
function makeTokenInstance(tokenName, canAttack) {
  const t = TOKENS[tokenName];
  return { uid: uid(), cardId: null, name: t.name, atk: t.atk, hp: t.hp, maxHp: t.hp, keywords: [...t.keywords], canAttack: !!canAttack, shielded: false, frozen: false, onDamage: null };
}

function log(state, msg, warn) {
  state.log = [...(state.log || []).slice(-40), { text: msg, warn: !!warn }];
}

function dealDamageToPlayer(state, playerIdx, amount) {
  const p = state.players[playerIdx];
  let remaining = amount;
  if (p.armor > 0) {
    const absorbed = Math.min(p.armor, remaining);
    p.armor -= absorbed;
    remaining -= absorbed;
  }
  p.health -= remaining;
}
function healPlayer(state, playerIdx, amount) {
  const p = state.players[playerIdx];
  p.health = Math.min(p.maxHealth, p.health + amount);
}
// ownerIdx = index of the player who CONTROLS the minion being damaged (needed for retaliate triggers)
// allowRetaliate = false when this damage was itself caused by a retaliate trigger, to prevent infinite chains
function damageMinion(state, minion, amount, ownerIdx, allowRetaliate = true) {
  if (minion.shielded) { minion.shielded = false; return; }
  minion.hp -= amount;
  if (minion.onDamage && allowRetaliate) applyEffects(state, minion.onDamage, ownerIdx, ownerIdx, null, false);
}
function destroyMinion(minion) {
  minion.hp = -9999;
}
function freezeMinion(minion) {
  minion.frozen = true;
  minion.canAttack = false;
}
function drawCard(state, playerIdx) {
  const p = state.players[playerIdx];
  if (p.deck.length === 0) {
    p.fatigue += 1;
    dealDamageToPlayer(state, playerIdx, p.fatigue);
    log(state, `${p.hero} takes ${p.fatigue} fatigue damage.`);
    return;
  }
  const cardId = p.deck.shift();
  if (p.hand.length >= 10) {
    const burned = findCard(cardId);
    log(state, `${p.hero} is holding too many cards. Drawn card '${burned.name}' was destroyed.`, true);
    return;
  }
  p.hand.push(cardId);
}

function removeDeadMinions(state) {
  state.players.forEach((p, idx) => {
    const dead = p.board.filter((m) => m.hp <= 0);
    if (dead.length === 0) return;
    p.board = p.board.filter((m) => m.hp > 0); // remove from the live board FIRST
    dead.forEach((m) => {
      const c = m.cardId ? findCard(m.cardId) : null;
      const dr = c && c.deathrattle;
      log(state, `${m.name} dies.`);
      if (dr) applyEffects(state, dr, idx, idx, null); // safe now — this minion is already off the board
    });
  });
}

function pickRandomN(arr, n) {
  const pool = [...arr];
  const picked = [];
  for (let i = 0; i < n && pool.length; i++) {
    const idx = Math.floor(Math.random() * pool.length);
    picked.push(pool.splice(idx, 1)[0]);
  }
  return picked;
}

function summonByName(state, targetIdx, cardName, count) {
  const card = findCardByName(cardName);
  if (!card) return;
  for (let i = 0; i < count; i++) {
    if (state.players[targetIdx].board.length < 6) state.players[targetIdx].board.push(makeMinionInstance(card.id, false));
  }
}

function addCardToHand(state, playerIdx, cardName) {
  const card = findCardByName(cardName);
  if (!card) return;
  const p = state.players[playerIdx];
  if (p.hand.length >= 10) { log(state, `${p.hero}'s hand is full — ${card.name} burns.`, true); return; }
  p.hand.push(card.id);
}

function applyEffects(state, effects, controllerIdx, sourceControllerIdx, chosen, allowRetaliate = true, sourceMinion = null) {
  const enemyIdx = controllerIdx === 0 ? 1 : 0;
  effects.forEach((eff) => {
    if (eff.type === "damage") {
      if (eff.target === "enemyHero") dealDamageToPlayer(state, enemyIdx, eff.amount);
      else if (eff.target === "ownHero") dealDamageToPlayer(state, controllerIdx, eff.amount);
      else if (eff.target === "allEnemyMinions") state.players[enemyIdx].board.forEach((m) => damageMinion(state, m, eff.amount, enemyIdx, allowRetaliate));
      else if (eff.target === "allEnemyCharacters") {
        state.players[enemyIdx].board.forEach((m) => damageMinion(state, m, eff.amount, enemyIdx, allowRetaliate));
        dealDamageToPlayer(state, enemyIdx, eff.amount);
      } else if (eff.target === "allFriendlyCharacters") {
        state.players[controllerIdx].board.forEach((m) => damageMinion(state, m, eff.amount, controllerIdx, allowRetaliate));
        dealDamageToPlayer(state, controllerIdx, eff.amount);
      } else if (eff.target === "everyone") {
        state.players[0].board.forEach((m) => damageMinion(state, m, eff.amount, 0, allowRetaliate));
        state.players[1].board.forEach((m) => damageMinion(state, m, eff.amount, 1, allowRetaliate));
        dealDamageToPlayer(state, 0, eff.amount);
        dealDamageToPlayer(state, 1, eff.amount);
      } else if (eff.target === "randomEnemyMinion") {
        const board = state.players[enemyIdx].board;
        if (board.length) damageMinion(state, board[Math.floor(Math.random() * board.length)], eff.amount, enemyIdx, allowRetaliate);
      } else if (eff.target === "randomEnemyMinions") {
        const picked = pickRandomN(state.players[enemyIdx].board, eff.count || 1);
        picked.forEach((m) => damageMinion(state, m, eff.amount, enemyIdx, allowRetaliate));
      } else if (eff.target === "randomEnemyAny") {
        const board = state.players[enemyIdx].board;
        const pool = [...board, "HERO"];
        const choice = pool[Math.floor(Math.random() * pool.length)];
        if (choice === "HERO") dealDamageToPlayer(state, enemyIdx, eff.amount);
        else damageMinion(state, choice, eff.amount, enemyIdx, allowRetaliate);
      } else if (eff.target === "randomAnyMinions") {
        const tagged = [...state.players[0].board.map((m) => ({ m, owner: 0 })), ...state.players[1].board.map((m) => ({ m, owner: 1 }))];
        const picked = pickRandomN(tagged, eff.count || 1);
        picked.forEach(({ m, owner }) => damageMinion(state, m, eff.amount, owner, allowRetaliate));
      } else if (eff.target === "chosenEnemyMinion" && chosen) {
        const board = state.players[enemyIdx].board;
        const m = board.find((x) => x.uid === chosen.uid);
        if (m) damageMinion(state, m, eff.amount, enemyIdx, allowRetaliate);
      } else if (eff.target === "chosenAny" && chosen) {
        if (chosen.type === "hero") dealDamageToPlayer(state, chosen.playerIdx, eff.amount);
        else {
          const board = state.players[chosen.playerIdx].board;
          const m = board.find((x) => x.uid === chosen.uid);
          if (m) damageMinion(state, m, eff.amount, chosen.playerIdx, allowRetaliate);
        }
      }
    } else if (eff.type === "battlecryAttack" && sourceMinion) {
      const atk = sourceMinion.atk;
      if (eff.target === "randomEnemyAny") {
        const board = state.players[enemyIdx].board;
        const pool = [...board, "HERO"];
        const choice = pool[Math.floor(Math.random() * pool.length)];
        if (choice === "HERO") dealDamageToPlayer(state, enemyIdx, atk);
        else {
          damageMinion(state, choice, atk, enemyIdx, allowRetaliate);
          damageMinion(state, sourceMinion, choice.atk, controllerIdx, allowRetaliate);
        }
      } else if (eff.target === "lowestAtkEnemyMinion") {
        const board = state.players[enemyIdx].board;
        if (board.length) {
          const target = board.reduce((a, b) => (b.atk < a.atk ? b : a), board[0]);
          damageMinion(state, target, atk, enemyIdx, allowRetaliate);
          damageMinion(state, sourceMinion, target.atk, controllerIdx, allowRetaliate);
        }
      } else if (eff.target === "allEnemyMinions") {
        const board = [...state.players[enemyIdx].board];
        for (const target of board) {
          if (sourceMinion.hp <= 0) break;
          if (target.hp <= 0) continue;
          damageMinion(state, target, atk, enemyIdx, allowRetaliate);
          damageMinion(state, sourceMinion, target.atk, controllerIdx, allowRetaliate);
        }
      }
    } else if (eff.type === "damageAndFreeze") {
      const picked = pickRandomN(state.players[enemyIdx].board, eff.count || 1);
      picked.forEach((m) => { damageMinion(state, m, eff.amount, enemyIdx, allowRetaliate); freezeMinion(m); });
    } else if (eff.type === "destroy") {
      if (eff.target === "randomEnemyMinion") {
        const board = state.players[enemyIdx].board;
        if (board.length) destroyMinion(board[Math.floor(Math.random() * board.length)]);
      } else if (eff.target === "allMinionsBoard") {
        state.players[0].board.forEach(destroyMinion);
        state.players[1].board.forEach(destroyMinion);
      }
    } else if (eff.type === "freeze") {
      if (eff.target === "allEnemyMinions") state.players[enemyIdx].board.forEach(freezeMinion);
      else if (eff.target === "randomEnemyMinion") {
        const board = state.players[enemyIdx].board;
        if (board.length) freezeMinion(board[Math.floor(Math.random() * board.length)]);
      } else if (eff.target === "randomEnemyMinions") {
        pickRandomN(state.players[enemyIdx].board, eff.count || 1).forEach(freezeMinion);
      }
    } else if (eff.type === "heal") {
      if (eff.target === "ownHero") healPlayer(state, controllerIdx, eff.amount);
      else if (eff.target === "enemyHero") healPlayer(state, enemyIdx, eff.amount);
      else if (eff.target === "allFriendlyMinions") state.players[controllerIdx].board.forEach((m) => { m.hp = Math.min(m.maxHp, m.hp + eff.amount); });
    } else if (eff.type === "healFull") {
      if (eff.target === "bothHeroes") { state.players[0].health = state.players[0].maxHealth; state.players[1].health = state.players[1].maxHealth; }
    } else if (eff.type === "draw") {
      for (let i = 0; i < eff.amount; i++) drawCard(state, controllerIdx);
    } else if (eff.type === "addCardToHand") {
      addCardToHand(state, controllerIdx, eff.cardName);
    } else if (eff.type === "armor") {
      if (eff.target === "enemyHero") state.players[enemyIdx].armor += eff.amount;
      else state.players[controllerIdx].armor += eff.amount;
    } else if (eff.type === "summon") {
      const targetIdx = eff.side === "enemy" ? enemyIdx : controllerIdx;
      if (eff.cardName) summonByName(state, targetIdx, eff.cardName, eff.count);
      else if (eff.token) {
        for (let i = 0; i < eff.count; i++) {
          if (state.players[targetIdx].board.length < 6) state.players[targetIdx].board.push(makeTokenInstance(eff.token, false));
        }
      }
    } else if (eff.type === "buff") {
      const addKw = (m) => { if (eff.addKeyword && !m.keywords.includes(eff.addKeyword)) m.keywords.push(eff.addKeyword); };
      if (eff.target === "chosenFriendly" && chosen) {
        const m = state.players[controllerIdx].board.find((x) => x.uid === chosen.uid);
        if (m) { m.atk += eff.atk; m.hp += eff.hp; m.maxHp += eff.hp; addKw(m); }
      } else if (eff.target === "allFriendlyMinions") {
        state.players[controllerIdx].board.forEach((m) => { m.atk += eff.atk; m.hp += eff.hp; m.maxHp += eff.hp; addKw(m); });
      } else if (eff.target === "allMinionsBoard") {
        state.players[0].board.forEach((m) => { m.atk += eff.atk; m.hp += eff.hp; m.maxHp += eff.hp; addKw(m); });
        state.players[1].board.forEach((m) => { m.atk += eff.atk; m.hp += eff.hp; m.maxHp += eff.hp; addKw(m); });
      }
    }
  });
  removeDeadMinions(state);
  checkWin(state);
}

function checkWin(state) {
  state.players.forEach((p, idx) => {
    if (p.health <= 0 && !state.winner) state.winner = idx === 0 ? 1 : 0;
  });
}

function startTurn(state) {
  const idx = state.turn;
  const p = state.players[idx];
  p.maxMana = Math.min(10, p.maxMana + 1);
  p.mana = p.maxMana;
  p.powerUsed = false;
  p.board.forEach((m) => {
    if (m.frozen) { m.frozen = false; m.canAttack = false; }
    else m.canAttack = true;
  });
  p.board.forEach((m) => {
    const c = m.cardId ? findCard(m.cardId) : null;
    if (c && c.onTurnStart) applyEffects(state, c.onTurnStart, idx, idx, null);
  });
  state.turnNumber += 1;
  drawCard(state, idx);
  checkWin(state);
  log(state, `--- ${p.hero}'s turn (${state.turnNumber}) ---`);
  if (p.board.length >= 6) {
    log(state, `${p.hero}'s board is full. Unable to play more than 6 minions at the same time until a minion dies.`, true);
  }
}

function initGame(gameId, p1, p2) {
  const state = {
    gameId, version: 1, turn: 0, turnNumber: 0,
    players: [freshPlayer(p1.sessionId, p1.hero, true, p1.deck, p1.displayName), freshPlayer(p2.sessionId, p2.hero, false, p2.deck, p2.displayName)],
    log: [], winner: null,
  };
  startTurn(state);
  return state;
}

/* =========================================================================
   CPU AI — decides one action at a time for an offline opponent.
   Called repeatedly (with the state re-fetched each time) until it returns
   an "endTurn" action, at which point the CPU's turn is over.
   Pure function: reads state, never mutates it.
   ========================================================================= */
function aiPickTarget(state, cpuIdx, needsTarget) {
  const enemyIdx = cpuIdx === 0 ? 1 : 0;
  const me = state.players[cpuIdx];
  const enemy = state.players[enemyIdx];
  if (needsTarget === "friendlyMinion") {
    if (me.board.length) return { uid: me.board[0].uid, type: "minion", playerIdx: cpuIdx };
    return null;
  }
  if (needsTarget === "anyMinion") {
    if (enemy.board.length) return { uid: enemy.board[0].uid, type: "minion", playerIdx: enemyIdx };
    if (me.board.length) return { uid: me.board[0].uid, type: "minion", playerIdx: cpuIdx };
    return null;
  }
  if (needsTarget === "enemyAny") {
    if (enemy.board.length) return { uid: enemy.board[0].uid, type: "minion", playerIdx: enemyIdx };
    return { type: "hero", playerIdx: enemyIdx };
  }
  if (needsTarget === "enemyMinion") {
    if (enemy.board.length) return { uid: enemy.board[0].uid, type: "minion", playerIdx: enemyIdx };
    return null;
  }
  if (needsTarget === "any") {
    return { type: "hero", playerIdx: enemyIdx };
  }
  return null;
}

function aiDecideAction(state, cpuIdx) {
  const enemyIdx = cpuIdx === 0 ? 1 : 0;
  const me = state.players[cpuIdx];
  const enemy = state.players[enemyIdx];

  // 1. Play the first affordable card in hand with a valid target (if it needs one).
  for (let i = 0; i < me.hand.length; i++) {
    const card = findCard(me.hand[i]);
    if (card.cost > me.mana) continue;
    if (card.type === "minion" && me.board.length >= 6) continue;
    let chosen = null;
    if (card.needsTarget) {
      chosen = aiPickTarget(state, cpuIdx, card.needsTarget);
      if (!chosen) continue;
    }
    return { type: "playCard", handIdx: i, chosen };
  }

  // 2. Use hero power if affordable and not yet used.
  const pw = HERO_POWERS[me.hero];
  if (!me.powerUsed && me.mana >= pw.cost) {
    if (!pw.needsTarget) return { type: "power" };
    const chosen = aiPickTarget(state, cpuIdx, pw.needsTarget);
    if (chosen) return { type: "power", chosen };
  }

  // 3. Attack with any minion that can still attack this turn.
  const attacker = me.board.find((m) => m.canAttack);
  if (attacker) {
    const tauntTargets = enemy.board.filter((m) => m.keywords.includes("Taunt"));
    if (tauntTargets.length) {
      return { type: "attack", attackerUid: attacker.uid, target: { type: "minion", uid: tauntTargets[0].uid } };
    }
    // Trade into something we can kill and survive against, if one exists.
    const goodTrade = enemy.board.find((m) => attacker.atk >= m.hp && m.atk < attacker.hp);
    if (goodTrade) return { type: "attack", attackerUid: attacker.uid, target: { type: "minion", uid: goodTrade.uid } };
    return { type: "attack", attackerUid: attacker.uid, target: { type: "hero" } };
  }

  // 4. Nothing left to do.
  return { type: "endTurn" };
}

/* =========================================================================
   REACT UI
   ========================================================================= */
const RARITY_STYLE = {
  common: { border: "#8a8a8a", bg: "#ffffff", label: "COMMON" },
  rare: { border: "#3a63d8", bg: "#ffffff", label: "RARE" },
  epic: { border: "#8a3ad8", bg: "#ffffff", label: "EPIC" },
  unique: { border: "#b8860b", bg: "linear-gradient(180deg,#fff8dc,#fdf0c8)", label: "UNIQUE" },
};

const FONT = `Consolas, "Lucida Console", "Courier New", monospace`;

const GLOBAL_STYLE = `
@keyframes heroAttackGlow {
  0%, 100% { box-shadow: 0 0 4px 1px rgba(192,57,43,0.45); }
  50% { box-shadow: 0 0 12px 5px rgba(192,57,43,0.9); }
}
@keyframes cardTextScroll {
  0%, 18% { transform: translateY(0); }
  50%, 68% { transform: translateY(var(--scroll-dist)); }
  100% { transform: translateY(0); }
}
@keyframes marqueeScroll {
  0%, 15% { transform: translateX(0); }
  50%, 65% { transform: translateX(var(--marquee-dist)); }
  100% { transform: translateX(0); }
}
`;

function AutoScrollText({ text, height, fontSize, duration = 5, bold = false, color = "#333" }) {
  const outerRef = useRef(null);
  const innerRef = useRef(null);
  const [dist, setDist] = useState(0);
  useEffect(() => {
    if (outerRef.current && innerRef.current) {
      const diff = innerRef.current.scrollHeight - outerRef.current.clientHeight;
      setDist(diff > 2 ? diff : 0);
    }
  }, [text, height]);
  return (
    <div ref={outerRef} style={{ height, overflow: "hidden", width: "100%", display: "flex", flexDirection: "column", justifyContent: dist > 0 ? "flex-start" : "center" }}>
      <div
        ref={innerRef}
        style={{
          fontSize, textAlign: "center", lineHeight: 1.15, color, fontWeight: bold ? 700 : 400, whiteSpace: "pre-line",
          "--scroll-dist": `-${dist}px`,
          animation: dist > 0 ? `cardTextScroll ${duration}s ease-in-out infinite` : "none",
        }}
      >
        {text}
      </div>
    </div>
  );
}

// Horizontal marquee: for a single line of text (like "Wanderer Lucas") that's
// too wide for its box. Slides right-to-left to reveal the hidden tail, then
// resets, on a loop. Falls back to plain centered text if it fits.
function MarqueeText({ text, width, fontSize, bold = false, color = "#111", duration = 6 }) {
  const outerRef = useRef(null);
  const innerRef = useRef(null);
  const [dist, setDist] = useState(0);
  useEffect(() => {
    if (outerRef.current && innerRef.current) {
      const diff = innerRef.current.scrollWidth - outerRef.current.clientWidth;
      setDist(diff > 2 ? diff : 0);
    }
  }, [text, width]);
  return (
    <div ref={outerRef} style={{ width, overflow: "hidden", whiteSpace: "nowrap" }}>
      <div
        ref={innerRef}
        style={{
          display: "inline-block", fontSize, fontWeight: bold ? 700 : 400, color,
          "--marquee-dist": `-${dist}px`,
          animation: dist > 0 ? `marqueeScroll ${duration}s ease-in-out infinite` : "none",
        }}
      >
        {text}
      </div>
    </div>
  );
}


function MiniCard({ cardId, onClick, disabled, small }) {
  const c = findCard(cardId);
  const r = RARITY_STYLE[c.rarity];
  const badgeReserve = small ? 20 : 22;
  return (
    <div
      onClick={disabled ? undefined : onClick}
      style={{
        width: small ? 92 : 112, minWidth: small ? 92 : 112, height: small ? 132 : 160,
        border: `2px ${c.type === "spell" ? "dashed" : "solid"} ${r.border}`, borderRadius: 6, background: r.bg,
        display: "flex", flexDirection: "column", alignItems: "center", padding: 4,
        cursor: disabled ? "default" : "pointer", opacity: disabled ? 0.55 : 1,
        boxShadow: "1px 1px 0 rgba(0,0,0,0.15)", position: "relative", fontFamily: FONT,
        userSelect: "none", boxSizing: "border-box",
      }}
      title={c.text || c.name}
    >
      <div style={{ position: "relative", width: "100%", flexShrink: 0 }}>
        <div style={{ position: "absolute", top: 0, left: 0, fontSize: small ? 10 : 11, fontWeight: 700, border: "1px solid #000", borderRadius: 3, minWidth: 14, textAlign: "center", lineHeight: "14px", background: "#fff", zIndex: 1 }}>{c.cost}</div>
        <div style={{ paddingLeft: badgeReserve, paddingRight: badgeReserve }}>
          <AutoScrollText text={c.name} height={small ? 18 : 20} fontSize={small ? 7.5 : 8.5} duration={7} bold />
        </div>
      </div>
      <div style={{ marginTop: 3, flexShrink: 0 }}><CardArt card={c} size={small ? 32 : 38} /></div>
      {c.text && <div style={{ marginTop: 4, width: "100%", flexShrink: 0 }}><AutoScrollText text={c.text} height={small ? 38 : 48} fontSize={small ? 7.5 : 8} duration={10} /></div>}
      <div style={{ marginTop: "auto", flexShrink: 0, display: "flex", justifyContent: "space-between", width: "100%", height: small ? 16 : 18 }}>
        {c.type === "spell" ? (
          <span style={{ margin: "auto", fontSize: small ? 8 : 9, fontWeight: 700, letterSpacing: 1 }}>SPELL</span>
        ) : (
          <>
            <div style={{ textAlign: "center", lineHeight: 1 }}>
              <div style={{ fontSize: small ? 5.5 : 6, color: "#555" }}>ATK</div>
              <div style={{ fontSize: small ? 10 : 11, fontWeight: 700 }}>{c.atk}</div>
            </div>
            <div style={{ textAlign: "center", lineHeight: 1 }}>
              <div style={{ fontSize: small ? 5.5 : 6, color: "#555" }}>HP</div>
              <div style={{ fontSize: small ? 10 : 11, fontWeight: 700 }}>{c.hp}</div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

function cardLikeForMinion(m) {
  if (m.cardId) return findCard(m.cardId);
  return { id: m.name, name: m.name, cost: null, atk: m.atk, hp: m.hp, rarity: "common", type: "minion", text: m.keywords && m.keywords.length ? m.keywords.join(", ") : "", keywords: m.keywords || [] };
}

function CardDetailModal({ card, onClose }) {
  const r = RARITY_STYLE[card.rarity];
  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: 240, border: `3px ${card.type === "spell" ? "dashed" : "solid"} ${r.border}`, borderRadius: 10,
          background: r.bg, padding: 16, fontFamily: FONT, boxShadow: "2px 2px 0 rgba(0,0,0,0.25)", textAlign: "center",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginBottom: 8 }}>
          {card.cost !== null && <div style={{ fontSize: 15, fontWeight: 700, border: "1px solid #000", borderRadius: 4, minWidth: 22, padding: "1px 3px" }}>{card.cost}</div>}
          <div style={{ fontSize: 14, fontWeight: 700 }}>{card.name}</div>
        </div>
        <div style={{ display: "flex", justifyContent: "center", marginBottom: 10 }}><CardArt card={card} size={80} /></div>
        {card.text && <div style={{ fontSize: 12, lineHeight: 1.4, color: "#333", marginBottom: 10 }}>{card.text}</div>}
        {card.type !== "spell" && (
          <div style={{ display: "flex", justifyContent: "center", gap: 24, marginBottom: 12, fontSize: 16, fontWeight: 700 }}>
            <div><div style={{ fontSize: 9, color: "#555" }}>ATK</div>{card.atk}</div>
            <div><div style={{ fontSize: 9, color: "#555" }}>HP</div>{card.hp}</div>
          </div>
        )}
        <button onClick={onClose} style={{ fontFamily: FONT, padding: "6px 18px", border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}>Close</button>
      </div>
    </div>
  );
}

function BoardMinion({ m, onClick, selected, targetable, isEnemy }) {
  const spent = !isEnemy && !m.canAttack;
  const cardDef = m.cardId ? findCard(m.cardId) : null;
  const rarity = cardDef ? cardDef.rarity : "common";
  const rStyle = RARITY_STYLE[rarity];
  const [showDetail, setShowDetail] = useState(false);
  const pressTimer = useRef(null);
  const longPressFired = useRef(false);

  const startPress = () => {
    longPressFired.current = false;
    pressTimer.current = setTimeout(() => {
      longPressFired.current = true;
      setShowDetail(true);
    }, 550);
  };
  const cancelPress = () => {
    if (pressTimer.current) { clearTimeout(pressTimer.current); pressTimer.current = null; }
  };
  const handleClick = () => {
    if (longPressFired.current) { longPressFired.current = false; return; }
    if (onClick) onClick();
  };
  const handleContextMenu = (e) => {
    e.preventDefault();
    setShowDetail(true);
  };

  return (
    <>
      <div
        onClick={handleClick}
        onContextMenu={handleContextMenu}
        onMouseDown={startPress}
        onMouseUp={cancelPress}
        onMouseLeave={cancelPress}
        onTouchStart={startPress}
        onTouchEnd={cancelPress}
        onTouchMove={cancelPress}
        style={{
          width: 70, minWidth: 70, height: 92, border: `2px solid ${selected ? "#000" : targetable ? "#c0392b" : rStyle.border}`,
          borderRadius: 5, background: rStyle.bg, display: "flex", flexDirection: "column", alignItems: "center",
          padding: 3, cursor: onClick ? "pointer" : "default", position: "relative", fontFamily: FONT,
          boxShadow: selected ? "0 0 0 2px #000" : targetable ? "0 0 0 2px #c0392b" : "1px 1px 0 rgba(0,0,0,0.12)",
          opacity: spent ? 0.45 : 1, filter: spent ? "grayscale(60%)" : "none", userSelect: "none",
        }}
        title={`${m.name} (right-click or long-press for details)`}
      >
        {m.keywords.includes("Taunt") && <div style={{ position: "absolute", top: -8, fontSize: 8, background: "#000", color: "#fff", padding: "0 3px", borderRadius: 3 }}>TAUNT</div>}
        {m.frozen && <div style={{ position: "absolute", top: -8, right: -4, fontSize: 8, background: "#dbeeff", border: "1px solid #2a6ebb", padding: "0 3px", borderRadius: 3 }}>FROZEN</div>}
        {m.shielded && <div style={{ position: "absolute", bottom: -8, right: -4, fontSize: 8, background: "#fff", border: "1px solid #000", padding: "0 3px", borderRadius: 3 }}>SHLD</div>}
        <CardArt card={m.cardId ? findCard(m.cardId) : { name: m.name, id: m.name }} size={40} />
        <div style={{ fontSize: 7, textAlign: "center", marginTop: 2, lineHeight: 1.05, height: 18, overflow: "hidden" }}>{m.name}</div>
        <div style={{ marginTop: "auto", display: "flex", justifyContent: "space-between", width: "100%", fontSize: 12, fontWeight: 700 }}>
          <span>{m.atk}</span><span style={{ color: m.hp < m.maxHp ? "#c0392b" : "#000" }}>{m.hp}</span>
        </div>
        {spent && <div style={{ fontSize: 6, color: "#888" }}>spent this turn</div>}
      </div>
      {showDetail && <CardDetailModal card={cardLikeForMinion(m)} onClose={() => setShowDetail(false)} />}
    </>
  );
}

function HeroPanel({ player, isEnemy, targetable, attackable, onClick, bgColor }) {
  const highlighted = targetable || attackable;
  const hpFrac = Math.max(0, Math.min(1, player.health / player.maxHealth));
  const barH = 58;
  const redH = Math.round(barH * (1 - hpFrac));
  const greenH = barH - redH;
  return (
    <div
      onClick={onClick}
      style={{
        display: "flex", alignItems: "center", gap: 8, width: 210, minWidth: 210, height: 84, minHeight: 84, boxSizing: "border-box",
        border: `2px solid ${highlighted ? "#c0392b" : "#000"}`, borderRadius: 8, padding: "8px 10px",
        background: bgColor || "#fff", cursor: onClick ? "pointer" : "default", fontFamily: FONT,
        boxShadow: highlighted ? "0 0 0 2px #c0392b" : "1px 1px 0 rgba(0,0,0,0.12)",
        animation: attackable ? "heroAttackGlow 1.3s ease-in-out infinite" : "none",
      }}
    >
      <div style={{ width: 9, minWidth: 9, height: barH, border: "1px solid #000", borderRadius: 3, overflow: "hidden", flexShrink: 0, display: "flex", flexDirection: "column" }} title="HP">
        <div style={{ height: redH, background: "#c0392b" }} />
        <div style={{ height: greenH, background: "#2ecc71" }} />
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <MarqueeText text={player.displayName ? `${player.hero} ${player.displayName}` : player.hero} width="100%" fontSize={12} bold duration={7} />
        <div style={{ fontSize: 10 }}>HP: {Math.max(0, player.health)}{player.armor > 0 ? ` (+${player.armor})` : ""}</div>
        <div style={{ fontSize: 10 }}>Mana: {player.mana}/{player.maxMana}</div>
        <div style={{ fontSize: 10 }}>Deck: {player.deck.length}</div>
      </div>
      <div style={{ width: 50, height: 50, minWidth: 50, border: "1px solid #000", borderRadius: 6, background: "rgba(255,255,255,0.55)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, overflow: "hidden" }}>
        {HERO_ART_OVERRIDES[player.hero] ? (
          <img src={HERO_ART_OVERRIDES[player.hero]} alt={player.hero} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <span style={{ fontSize: 8, color: "#888" }}>IMG</span>
        )}
      </div>
    </div>
  );
}

/* ---------- ranked tiers ---------- */
const TIERS = ["Bronze", "Silver", "Gold", "Legendary"];
function applyMatchResult(profile, won) {
  const p = { wins: profile.wins || 0, losses: profile.losses || 0, winStreak: profile.winStreak || 0, tier: profile.tier || "Bronze" };
  if (won) {
    p.wins += 1;
    p.winStreak += 1;
    if (p.winStreak >= 5 && TIERS.indexOf(p.tier) < TIERS.length - 1) {
      p.tier = TIERS[TIERS.indexOf(p.tier) + 1];
      p.winStreak = 0;
    }
  } else {
    p.losses += 1;
    p.winStreak = 0;
  }
  return p;
}

function LeaderboardScreen({ onBack }) {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    (async () => {
      try {
        const snap = await getDocs(query(collection(db, "users"), orderBy("wins", "desc"), limit(50)));
        setRows(snap.docs.map((d) => ({ id: d.id, ...d.data() })));
      } catch (e) {
        console.error("Leaderboard load failed:", e);
      }
      setLoading(false);
    })();
  }, []);
  const tierRank = { Bronze: 0, Silver: 1, Gold: 2, Legendary: 3 };
  const sorted = [...rows].sort((a, b) => (tierRank[b.tier || "Bronze"] - tierRank[a.tier || "Bronze"]) || ((b.wins || 0) - (a.wins || 0)));

  return (
    <div style={{ fontFamily: FONT, padding: 20, maxWidth: 640, margin: "0 auto" }}>
      <h2 style={{ fontSize: 18, borderBottom: "2px solid #000", paddingBottom: 6 }}>Leaderboard</h2>
      {loading ? (
        <p style={{ fontSize: 12 }}>Loading...</p>
      ) : sorted.length === 0 ? (
        <p style={{ fontSize: 12, color: "#666" }}>No ranked games played yet.</p>
      ) : (
        <table style={{ width: "100%", fontSize: 12, borderCollapse: "collapse", marginTop: 10 }}>
          <thead>
            <tr style={{ textAlign: "left", borderBottom: "2px solid #000" }}>
              <th style={{ padding: "4px 2px" }}>#</th>
              <th style={{ padding: "4px 2px" }}>Player</th>
              <th style={{ padding: "4px 2px" }}>Tier</th>
              <th style={{ padding: "4px 2px", textAlign: "center" }}>W</th>
              <th style={{ padding: "4px 2px", textAlign: "center" }}>L</th>
              <th style={{ padding: "4px 2px", textAlign: "center" }}>Streak</th>
            </tr>
          </thead>
          <tbody>
            {sorted.map((r, i) => (
              <tr key={r.id} style={{ borderTop: "1px solid #ddd" }}>
                <td style={{ padding: "4px 2px" }}>{i + 1}</td>
                <td style={{ padding: "4px 2px" }}>{r.displayName || "Player"}</td>
                <td style={{ padding: "4px 2px" }}>{r.tier || "Bronze"}</td>
                <td style={{ padding: "4px 2px", textAlign: "center" }}>{r.wins || 0}</td>
                <td style={{ padding: "4px 2px", textAlign: "center" }}>{r.losses || 0}</td>
                <td style={{ padding: "4px 2px", textAlign: "center" }}>{r.winStreak || 0}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
      <button onClick={onBack} style={{ marginTop: 16, padding: "8px 16px", fontFamily: FONT, fontSize: 13, border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>Back</button>
    </div>
  );
}

