function DeckBuilderScreen({ hero, initialDeck, onSave, onCancel }) {
  const pool = CARD_DB.filter((c) => c.hero === hero || !c.hero);
  const [counts, setCounts] = useState(() => {
    const c = {};
    if (initialDeck) initialDeck.forEach((id) => { c[id] = (c[id] || 0) + 1; });
    return c;
  });
  const [saveError, setSaveError] = useState(null);
  const total = Object.values(counts).reduce((a, b) => a + b, 0);
  const rarityOrder = ["common", "rare", "epic", "unique"];

  function addCopy(card) {
    const cur = counts[card.id] || 0;
    if (cur >= card.copies || total >= 30) return;
    setCounts({ ...counts, [card.id]: cur + 1 });
  }
  function removeCopy(cardId) {
    const cur = counts[cardId] || 0;
    if (cur <= 1) { const next = { ...counts }; delete next[cardId]; setCounts(next); }
    else setCounts({ ...counts, [cardId]: cur - 1 });
  }
  function handleSave() {
    const deck = Object.entries(counts).flatMap(([id, n]) => Array(n).fill(id));
    if (!validateDeck(deck, hero)) {
      setSaveError("This deck isn't legal — check you have exactly 30 cards, only cards for this hero or neutrals, and no more copies than allowed.");
      return;
    }
    setSaveError(null);
    onSave(deck);
  }

  const heroCards = pool.filter((c) => c.hero === hero);
  const neutralCards = pool.filter((c) => !c.hero);
  const deckEntries = Object.entries(counts).filter(([, n]) => n > 0)
    .map(([id, n]) => ({ card: findCard(id), n }))
    .sort((a, b) => a.card.cost - b.card.cost);

  function renderSection(title, cards) {
    const sorted = rarityOrder.flatMap((r) => cards.filter((c) => c.rarity === r));
    return (
      <div key={title}>
        <div style={{ fontWeight: 700, marginTop: 14, marginBottom: 6, fontSize: 12 }}>{title}</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
          {sorted.map((c) => {
            const cnt = counts[c.id] || 0;
            const atCap = cnt >= c.copies;
            const deckFull = total >= 30;
            return (
              <div key={c.id} style={{ position: "relative" }} onClick={() => addCopy(c)}>
                <MiniCard cardId={c.id} small disabled={atCap || deckFull} />
                {cnt > 0 && <div style={{ position: "absolute", top: -6, right: -6, background: "#000", color: "#fff", borderRadius: "50%", width: 18, height: 18, fontSize: 10, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONT, border: "1px solid #fff" }}>{cnt}</div>}
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div style={{ fontFamily: FONT, padding: 16, maxWidth: 900, margin: "0 auto" }}>
      <h2 style={{ fontSize: 18, borderBottom: "2px solid #000", paddingBottom: 6 }}>Deck Builder — {hero}</h2>
      <div style={{ fontSize: 12, color: "#555", marginTop: 4 }}>Tap a card to add a copy. Tap a card in "Your Deck" to remove one. Max 2 copies (1 for uniques).</div>
      <div style={{ display: "flex", gap: 18, flexWrap: "wrap", marginTop: 10 }}>
        <div style={{ flex: 2, minWidth: 280, maxHeight: 480, overflowY: "auto", paddingRight: 6 }}>
          {renderSection(`${hero} cards`, heroCards)}
          {renderSection("Neutral cards", neutralCards)}
        </div>
        <div style={{ flex: 1, minWidth: 220, borderLeft: "1px solid #ccc", paddingLeft: 14 }}>
          <div style={{ fontWeight: 700, marginBottom: 6, fontSize: 13, color: total === 30 ? "#1a7a1a" : "#c0392b" }}>Your Deck — {total}/30</div>
          <div style={{ maxHeight: 420, overflowY: "auto" }}>
            {deckEntries.length === 0 && <div style={{ fontSize: 11, color: "#888" }}>No cards yet — tap cards on the left to add them.</div>}
            {deckEntries.map(({ card, n }) => (
              <div key={card.id} onClick={() => removeCopy(card.id)} style={{ display: "flex", justifyContent: "space-between", fontSize: 11, padding: "4px 2px", borderBottom: "1px solid #eee", cursor: "pointer" }} title="Click to remove one copy">
                <span>[{card.cost}] {card.name}</span>
                <span>x{n}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
      <div style={{ marginTop: 16, display: "flex", gap: 10, alignItems: "center" }}>
        <button
          disabled={total !== 30}
          onClick={handleSave}
          style={{ padding: "10px 18px", fontFamily: FONT, fontSize: 13, fontWeight: 700, border: "2px solid #000", background: total === 30 ? "#000" : "#ccc", color: "#fff", cursor: total === 30 ? "pointer" : "default", borderRadius: 4 }}
        >
          Save Deck ({total}/30)
        </button>
        <button onClick={() => setCounts({})} style={{ padding: "10px 14px", fontFamily: FONT, fontSize: 13, border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>Clear</button>
        <button onClick={onCancel} style={{ padding: "10px 14px", fontFamily: FONT, fontSize: 13, border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>Cancel</button>
      </div>
      {saveError && <div style={{ marginTop: 8, fontSize: 11, color: "#c0392b", background: "#fff3f2", border: "1px solid #c0392b", padding: "6px 8px", borderRadius: 4 }}>{saveError}</div>}
    </div>
  );
}

function SearchingScreen({ hero, onCancel }) {
  const [dots, setDots] = useState("");
  useEffect(() => {
    const t = setInterval(() => setDots((d) => (d.length >= 3 ? "" : d + ".")), 500);
    return () => clearInterval(t);
  }, []);
  return (
    <div style={{ fontFamily: FONT, padding: 30, textAlign: "center" }}>
      <h2>Searching for opponent{dots}</h2>
      <p style={{ fontSize: 12, color: "#555" }}>Playing as {hero}. Checks the queue every couple seconds — no need to keep this tab focused.</p>
      <button onClick={onCancel} style={{ marginTop: 16, fontFamily: FONT, padding: "6px 14px", border: "2px solid #000", background: "#fff", cursor: "pointer" }}>Cancel</button>
    </div>
  );
}

/* ---------- Main game screen ---------- */
function GameScreen({ state, myIdx, onAction, onConcede, actionError, onSync, onBackToMenu }) {
  const me = state.players[myIdx];
  const opp = state.players[myIdx === 0 ? 1 : 0];
  const myTurn = state.turn === myIdx;
  const [pending, setPending] = useState(null); // {kind:'card'|'power', idx?, needsTarget}
  const [attacker, setAttacker] = useState(null); // uid of selected attacking minion
  const [confirmingIdx, setConfirmingIdx] = useState(null); // hand index awaiting Yes/No confirmation
  const [confirmConcede, setConfirmConcede] = useState(false);
  const [notice, setNotice] = useState(null); // transient feedback message
  const noticeTimer = useRef(null);

  const cancelPending = () => { setPending(null); setAttacker(null); };
  const flash = (msg) => {
    setNotice(msg);
    if (noticeTimer.current) clearTimeout(noticeTimer.current);
    noticeTimer.current = setTimeout(() => setNotice(null), 2200);
  };
  useEffect(() => () => { if (noticeTimer.current) clearTimeout(noticeTimer.current); }, []);

  const oppHasTaunt = opp.board.some((m) => m.keywords.includes("Taunt"));
  const canAttackEnemyHero = myTurn && !!attacker && !oppHasTaunt;
  const boardFull = me.board.length >= 6;

  const logRef = useRef(null);
  useEffect(() => {
    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
  }, [state.log]);

  function handleCardClick(handIdx) {
    if (!myTurn) return;
    const cardId = me.hand[handIdx];
    const c = findCard(cardId);
    if (c.cost > me.mana) return;
    if (c.type === "minion" && boardFull) { flash("Board is full."); return; }
    setConfirmingIdx(handIdx);
  }
  function confirmPlayCard(handIdx) {
    setConfirmingIdx(null);
    const cardId = me.hand[handIdx];
    const c = findCard(cardId);
    if (c.needsTarget) { setAttacker(null); setPending({ kind: "card", handIdx, needsTarget: c.needsTarget }); return; }
    onAction({ type: "playCard", handIdx });
  }
  function handlePower() {
    if (!myTurn || me.powerUsed || me.mana < HERO_POWERS[me.hero].cost) return;
    const nt = HERO_POWERS[me.hero].needsTarget;
    if (nt) { setAttacker(null); setPending({ kind: "power", needsTarget: nt }); return; }
    onAction({ type: "power" });
  }
  function handleMinionClick(m, isEnemy, ownerIdx) {
    if (pending) {
      // resolving a target
      if (pending.needsTarget === "enemyMinion" && isEnemy) resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      if (pending.needsTarget === "friendlyMinion" && !isEnemy) resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      if (pending.needsTarget === "any") resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      if (pending.needsTarget === "enemyAny" && isEnemy) resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      if (pending.needsTarget === "anyMinion") resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      return;
    }
    if (!myTurn) return;
    if (!isEnemy) {
      if (!m.canAttack) { flash(m.frozen ? `${m.name} is frozen and can't attack.` : `${m.name} has already attacked this turn.`); return; }
      setAttacker(attacker === m.uid ? null : m.uid);
      return;
    }
    if (isEnemy) {
      if (!attacker) { flash("Select one of your minions first, then choose a target."); return; }
      if (oppHasTaunt && !m.keywords.includes("Taunt")) { flash("A Taunt minion is guarding the enemy — attack it first."); return; }
      onAction({ type: "attack", attackerUid: attacker, target: { type: "minion", uid: m.uid } });
      setAttacker(null);
    }
  }
  function handleHeroClick(isEnemy, playerIdx) {
    if (pending) {
      if (pending.needsTarget === "any") resolveTarget({ type: "hero", playerIdx });
      if (pending.needsTarget === "enemyAny" && isEnemy) resolveTarget({ type: "hero", playerIdx });
      return;
    }
    if (!myTurn) return;
    if (isEnemy) {
      if (!attacker) { flash("Select one of your minions first, then choose a target."); return; }
      if (oppHasTaunt) { flash("A Taunt minion is guarding the enemy hero — attack it first."); return; }
      onAction({ type: "attack", attackerUid: attacker, target: { type: "hero" } });
      setAttacker(null);
    }
  }
  function resolveTarget(chosen) {
    if (pending.kind === "card") onAction({ type: "playCard", handIdx: pending.handIdx, chosen });
    else onAction({ type: "power", chosen });
    setPending(null);
  }

  return (
    <div style={{ fontFamily: FONT, padding: 12, maxWidth: 900, margin: "0 auto" }}>
      {state.winner !== null && (() => {
        const iWon = state.winner === myIdx;
        const losingHero = state.players[state.winner === 0 ? 1 : 0].hero;
        const gif = HERO_LOSE_GIF_OVERRIDES[losingHero];
        return (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 200 }}>
            <div style={{ background: "#fff", border: "3px solid #000", borderRadius: 10, padding: 24, textAlign: "center", minWidth: 260, boxShadow: "3px 3px 0 rgba(0,0,0,0.3)" }}>
              <h1 style={{ fontSize: 34, margin: 0, letterSpacing: 2, fontFamily: FONT, color: iWon ? "#1a7a1a" : "#c0392b" }}>
                {iWon ? "YOU WIN" : "YOU LOST"}
              </h1>
              <div style={{ fontSize: 11, color: "#666", marginTop: 4 }}>{losingHero} falls in the wasteland.</div>
              <div style={{ width: 200, height: 200, border: "2px solid #000", borderRadius: 6, background: "#f2f2f2", display: "flex", alignItems: "center", justifyContent: "center", margin: "16px auto 0", overflow: "hidden" }}>
                {gif ? (
                  gif.startsWith("data:video") ? (
                    <video src={gif} autoPlay loop muted playsInline style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  ) : (
                    <img src={gif} alt={`${losingHero} defeated`} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  )
                ) : (
                  <span style={{ fontSize: 11, color: "#999" }}>{losingHero} defeat GIF</span>
                )}
              </div>
              <button
                onClick={onBackToMenu}
                style={{ marginTop: 18, padding: "10px 20px", fontFamily: FONT, fontSize: 13, fontWeight: 700, border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}
              >
                Back to Menu
              </button>
            </div>
          </div>
        );
      })()}
      {pending && (
        <div style={{ textAlign: "center", marginBottom: 6, fontSize: 12 }}>
          Select a target… <button onClick={cancelPending} style={{ fontFamily: FONT, marginLeft: 8, cursor: "pointer" }}>cancel</button>
        </div>
      )}
      {notice && (
        <div style={{ textAlign: "center", marginBottom: 6, fontSize: 12, background: "#fff3f2", border: "1px solid #c0392b", color: "#8a1f14", padding: "4px 8px", borderRadius: 4 }}>
          {notice}
        </div>
      )}
      {actionError && (
        <div style={{ textAlign: "center", marginBottom: 6, fontSize: 12, background: "#fff3f2", border: "1px solid #c0392b", color: "#8a1f14", padding: "4px 8px", borderRadius: 4 }}>
          {actionError}
        </div>
      )}

      {/* opponent row */}
      <div style={{ position: "relative", marginBottom: 6, minHeight: 84 }}>
        <HeroPanel player={opp} isEnemy targetable={!!pending && (pending.needsTarget === "any" || pending.needsTarget === "enemyAny")} attackable={canAttackEnemyHero} onClick={() => handleHeroClick(true, myIdx === 0 ? 1 : 0)} bgColor={HERO_COLORS[opp.hero]} />
        <div style={{ position: "absolute", top: 0, left: 220, width: 104, maxHeight: 56, overflowY: "auto", display: "flex", flexWrap: "wrap", alignContent: "flex-start", gap: 3 }}>
          {Array.from({ length: opp.hand.length }).map((_, i) => (
            <div key={i} style={{ width: 18, height: 25, border: "2px solid #000", borderRadius: 3, flexShrink: 0, background: "repeating-linear-gradient(45deg,#000,#000 2px,#fff 2px,#fff 4px)" }} />
          ))}
        </div>
      </div>
      <div style={{ display: "flex", gap: 6, minHeight: 96, borderBottom: "1px dashed #999", paddingBottom: 8, marginBottom: 8, flexWrap: "wrap" }}>
        {opp.board.map((m) => (
          <BoardMinion key={m.uid} m={m} isEnemy targetable={!!attacker || (pending && (pending.needsTarget === "enemyMinion" || pending.needsTarget === "any" || pending.needsTarget === "enemyAny" || pending.needsTarget === "anyMinion"))} onClick={() => handleMinionClick(m, true, myIdx === 0 ? 1 : 0)} />
        ))}
      </div>

      {/* board separator / log + concede */}
      <div style={{ display: "flex", gap: 8, alignItems: "stretch", marginBottom: 8 }}>
        <div ref={logRef} style={{ flex: 1, fontSize: 10, color: "#666", maxHeight: 46, overflowY: "auto", border: "1px solid #ccc", padding: 4, background: "#fafafa" }}>
          {(state.log || []).slice(-6).map((l, i) => {
            const text = typeof l === "string" ? l : l.text;
            const warn = typeof l === "string" ? false : l.warn;
            return <div key={i} style={warn ? { color: "#c0392b", fontWeight: 700 } : undefined}>{text}</div>;
          })}
        </div>
        <button onClick={onSync} title="Force-refresh the game state" style={{ fontFamily: FONT, padding: "6px 12px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4, fontSize: 11 }}>Sync</button>
        <button onClick={() => setConfirmConcede(true)} style={{ fontFamily: FONT, padding: "6px 14px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4, fontSize: 11 }}>Concede</button>
      </div>

      {/* my board (3-column grid of minions, up to 2 rows / 6 minions) + End Turn pinned right, under Concede */}
      <div style={{ display: "flex", gap: 8, alignItems: "flex-start", borderTop: "1px dashed #999", paddingTop: 8, marginBottom: 8 }}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 70px)", gridAutoRows: 92, gap: 6 }}>
          {me.board.map((m) => (
            <BoardMinion key={m.uid} m={m} selected={attacker === m.uid} targetable={pending && (pending.needsTarget === "friendlyMinion" || pending.needsTarget === "anyMinion")} onClick={() => handleMinionClick(m, false, myIdx)} />
          ))}
        </div>
        <button
          onClick={() => onAction({ type: "endTurn" })}
          disabled={!myTurn}
          style={{
            marginLeft: "auto", flexShrink: 0, width: 70, height: 92, boxSizing: "border-box",
            fontFamily: FONT, border: "2px solid #000", borderRadius: 5,
            background: myTurn ? "#000" : "#ccc", cursor: myTurn ? "pointer" : "default",
            display: "flex", alignItems: "center", justifyContent: "center", padding: 4,
          }}
        >
          <AutoScrollText text={myTurn ? "End\nTurn" : "Wait\nFor\nOpponent"} height={60} fontSize={11} duration={6} bold color="#fff" />
        </button>
      </div>

      {/* my hero row */}
      <div style={{ display: "flex", justifyContent: "flex-start", alignItems: "stretch", gap: 8, marginBottom: 8 }}>
        <HeroPanel player={me} targetable={pending && pending.needsTarget === "any"} onClick={() => handleHeroClick(false, myIdx)} bgColor={HERO_COLORS[me.hero]} />
        <button
          onClick={handlePower}
          disabled={!myTurn || me.powerUsed || me.mana < HERO_POWERS[me.hero].cost}
          style={{
            marginLeft: "auto", flexShrink: 0,
            fontFamily: FONT, padding: "8px 10px", border: "2px solid #000", borderRadius: 8,
            background: me.powerUsed ? "#ddd" : "#fff", cursor: myTurn ? "pointer" : "default",
            width: 130, height: 84, boxSizing: "border-box",
            display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center",
          }}
        >
          <AutoScrollText text={`${HERO_POWERS[me.hero].name} (${HERO_POWERS[me.hero].cost})`} height={24} fontSize={11} duration={6} bold />
          <div style={{ marginTop: 4, width: "100%" }}>
            <AutoScrollText text={HERO_POWERS[me.hero].desc} height={34} fontSize={9} duration={8} color="#444" />
          </div>
        </button>
      </div>

      {/* hand */}
      <div style={{ display: "flex", gap: 6, overflowX: "auto", paddingBottom: 6 }}>
        {me.hand.map((cardId, i) => {
          const c = findCard(cardId);
          const disabled = !myTurn || c.cost > me.mana || (c.type === "minion" && boardFull);
          return <MiniCard key={i} cardId={cardId} onClick={() => handleCardClick(i)} disabled={disabled} />;
        })}
      </div>

      {/* play confirmation modal */}
      {confirmingIdx !== null && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.35)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50 }} onClick={() => setConfirmingIdx(null)}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", border: "2px solid #000", borderRadius: 8, padding: 18, fontFamily: FONT, textAlign: "center", minWidth: 220 }}>
            <div style={{ display: "flex", justifyContent: "center", marginBottom: 8 }}>
              <MiniCard cardId={me.hand[confirmingIdx]} disabled />
            </div>
            <div style={{ marginBottom: 12, fontSize: 13 }}>Play this card?</div>
            <div style={{ display: "flex", gap: 10, justifyContent: "center" }}>
              <button onClick={() => confirmPlayCard(confirmingIdx)} style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}>Yes</button>
              <button onClick={() => setConfirmingIdx(null)} style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>No</button>
            </div>
          </div>
        </div>
      )}

      {/* concede confirmation modal */}
      {confirmConcede && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.35)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50 }} onClick={() => setConfirmConcede(false)}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", border: "2px solid #000", borderRadius: 8, padding: 18, fontFamily: FONT, textAlign: "center", minWidth: 240 }}>
            <div style={{ marginBottom: 12, fontSize: 13 }}>Concede this game? You will lose.</div>
            <div style={{ display: "flex", gap: 10, justifyContent: "center" }}>
              <button onClick={() => { setConfirmConcede(false); onConcede(); }} style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}>Yes</button>
              <button onClick={() => setConfirmConcede(false)} style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>No</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

/* =========================================================================
   APP — orchestrates screens + matchmaking + polling
   ========================================================================= */
export default function App() {
  const [screen, setScreen] = useState("select"); // select | deckbuilder | searching | game | leaderboard
  const [hero, setHero] = useState(null);
  const [gameId, setGameId] = useState(null);
  const [myIdx, setMyIdx] = useState(null);
  const [gameState, setGameState] = useState(null);
  const [actionError, setActionError] = useState(null);
  const [screenNotice, setScreenNotice] = useState(null);
  const [customDecks, setCustomDecks] = useState({}); // hero -> array of 30 card ids
  const [deckBuilderHero, setDeckBuilderHero] = useState(null);
  const [isCpuMatch, setIsCpuMatch] = useState(false);
  const [user, setUser] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [myProfile, setMyProfile] = useState(null);
  const sessionId = user ? user.uid : null;
  const myFirstName = user && user.displayName ? user.displayName.split(" ")[0] : "";
  const matchListenerRef = useRef(null); // holds the current onSnapshot unsubscribe function
  const lastFailedStateRef = useRef(null);
  const resultRecordedForRef = useRef(null); // gameId whose result we already recorded, so we never double-count

  useEffect(() => {
    const unsub = onAuthStateChanged(auth, (u) => { setUser(u); setAuthLoading(false); });
    return unsub;
  }, []);

  useEffect(() => () => { if (matchListenerRef.current) matchListenerRef.current(); }, []);

  useEffect(() => {
    if (!user) { setMyProfile(null); return; }
    (async () => {
      const snap = await fGet(["users", user.uid]);
      setMyProfile(snap);
    })();
  }, [user]);

  // Record the ranked result exactly once per match, and never for CPU games.
  useEffect(() => {
    if (!gameState || gameState.winner === null || !user || isCpuMatch) return;
    if (resultRecordedForRef.current === gameId) return;
    resultRecordedForRef.current = gameId;
    (async () => {
      const won = gameState.winner === myIdx;
      const existing = (await fGet(["users", user.uid])) || {};
      const updated = applyMatchResult(existing, won);
      const profile = { ...updated, displayName: user.displayName || "Player" };
      await fSet(["users", user.uid], profile);
      setMyProfile(profile);
    })();
  }, [gameState?.winner, gameId, user, isCpuMatch, myIdx]);

  useEffect(() => {
    if (!user) { setCustomDecks({}); return; }
    (async () => {
      const entries = await Promise.all(HEROES.map(async (h) => {
        const data = await fGet(["users", user.uid, "decks", h]);
        return [h, data ? data.deck : null];
      }));
      const loaded = {};
      entries.forEach(([h, deck]) => { if (validateDeck(deck, h)) loaded[h] = deck; });
      setCustomDecks(loaded);
    })();
  }, [user]);

  function openDeckBuilder(chosenHero) {
    setDeckBuilderHero(chosenHero);
    setScreen("deckbuilder");
  }

  async function saveCustomDeck(chosenHero, deckArray) {
    await fSet(["users", user.uid, "decks", chosenHero], { deck: deckArray });
    setCustomDecks((prev) => ({ ...prev, [chosenHero]: deckArray }));
    setScreen("select");
  }

  function startCpuMatch(chosenHero) {
    const myDeck = customDecks[chosenHero] || null;
    const cpuHero = HEROES[Math.floor(Math.random() * HEROES.length)];
    const newId = "cpu_" + uid();
    const state = initGame(newId, { sessionId, hero: chosenHero, deck: myDeck, displayName: myFirstName }, { sessionId: "CPU", hero: cpuHero, deck: null, displayName: "CPU" });
    setGameId(newId);
    setMyIdx(0);
    setHero(chosenHero);
    setIsCpuMatch(true);
    setGameState(state);
    setScreen("game");
  }

  // Drive the CPU's turn: one action at a time, with a short pause between each for pacing.
  useEffect(() => {
    if (!isCpuMatch || !gameState || gameState.winner !== null) return;
    if (gameState.turn !== 1) return;
    const timer = setTimeout(() => {
      const action = aiDecideAction(gameState, 1);
      handleAction(action, 1);
    }, 700);
    return () => clearTimeout(timer);
  }, [isCpuMatch, gameState]);

  // Real-time listener on a live match document — replaces the old polling loop.
  function beginListening(matchId) {
    if (matchListenerRef.current) matchListenerRef.current();
    matchListenerRef.current = onSnapshot(doc(db, "matches", matchId), (snap) => {
      if (!snap.exists()) return;
      const g = snap.data();
      setGameState((prev) => (!prev || g.version >= prev.version ? g : prev));
    });
  }

  // Atomically try to claim a waiting player's queue entry and turn it into a match.
  // Uses a Firestore transaction so two people can't both claim the same waiting
  // player at once.
  async function claimQueueEntry(targetUid, matchId, myInfo) {
    try {
      await runTransaction(db, async (tx) => {
        const ref = doc(db, "matchmakingQueue", targetUid);
        const snap = await tx.get(ref);
        if (!snap.exists() || snap.data().matchedInto) throw new Error("already taken");
        const theirInfo = snap.data();
        const state = initGame(matchId, { sessionId: theirInfo.uid, hero: theirInfo.hero, deck: theirInfo.deck, displayName: theirInfo.displayName }, { sessionId: myInfo.uid, hero: myInfo.hero, deck: myInfo.deck, displayName: myInfo.displayName });
        tx.set(doc(db, "matches", matchId), { ...state, playerIds: [theirInfo.uid, myInfo.uid] });
        tx.update(ref, { matchedInto: matchId });
      });
      return true;
    } catch (e) {
      return false;
    }
  }

  // While waiting, listen on our own queue document for someone else to match with us.
  function listenForMatch(myUid) {
    if (matchListenerRef.current) matchListenerRef.current();
    matchListenerRef.current = onSnapshot(doc(db, "matchmakingQueue", myUid), async (snap) => {
      if (!snap.exists()) return;
      const data = snap.data();
      if (!data.matchedInto) return;
      if (matchListenerRef.current) { matchListenerRef.current(); matchListenerRef.current = null; }
      const matchSnap = await getDoc(doc(db, "matches", data.matchedInto));
      if (!matchSnap.exists()) { setScreen("select"); return; }
      const state = matchSnap.data();
      fDelete(["matchmakingQueue", myUid]);
      const legit = state.players.every((p) => validateDeck([...p.deck, ...p.hand], p.hero));
      if (!legit) {
        setScreenNotice("This match couldn't be verified (invalid deck detected) — please search again.");
        setTimeout(() => setScreenNotice(null), 6000);
        fDelete(["matches", data.matchedInto]);
        setScreen("select");
        return;
      }
      setGameId(data.matchedInto);
      setMyIdx(0);
      setGameState(state);
      setScreen("game");
      beginListening(data.matchedInto);
    });
  }

  async function startSearch(chosenHero) {
    setIsCpuMatch(false);
    setHero(chosenHero);
    setScreen("searching");
    const myDeck = customDecks[chosenHero] || null;
    const myUid = user.uid;

    // look for someone already waiting
    const qSnap = await getDocs(query(collection(db, "matchmakingQueue"), orderBy("createdAtMs"), limit(8)));
    const candidates = qSnap.docs
      .map((d) => d.data())
      .filter((d) => d.uid !== myUid && !d.matchedInto && Date.now() - (d.createdAtMs || 0) < 45000);

    for (const cand of candidates) {
      const matchId = uid();
      const claimed = await claimQueueEntry(cand.uid, matchId, { uid: myUid, hero: chosenHero, deck: myDeck, displayName: myFirstName });
      if (claimed) {
        const matchSnap = await getDoc(doc(db, "matches", matchId));
        setGameId(matchId);
        setMyIdx(1);
        setGameState(matchSnap.data());
        setScreen("game");
        beginListening(matchId);
        return;
      }
    }

    // nobody available — become the waiting player
    await setDoc(doc(db, "matchmakingQueue", myUid), {
      uid: myUid, hero: chosenHero, deck: myDeck,
      displayName: myFirstName,
      createdAtMs: Date.now(),
    });
    listenForMatch(myUid);
  }

  async function cancelSearch() {
    if (matchListenerRef.current) { matchListenerRef.current(); matchListenerRef.current = null; }
    if (user) await fDelete(["matchmakingQueue", user.uid]);
    setScreen("select");
  }

  async function pushState(newState) {
    newState.version = (gameState?.version || 1) + 1;
    setGameState(newState);
    if (isCpuMatch) return;
    const ok = await fSet(["matches", gameId], newState);
    if (!ok) {
      lastFailedStateRef.current = newState;
      setActionError("Your move didn't reach the opponent (connection issue). Tap Sync to retry.");
      setTimeout(() => setActionError(null), 6000);
    } else {
      lastFailedStateRef.current = null;
    }
  }

  async function manualSync() {
    if (!gameId || isCpuMatch) return;
    if (lastFailedStateRef.current) {
      const ok = await fSet(["matches", gameId], lastFailedStateRef.current);
      if (ok) { lastFailedStateRef.current = null; setActionError(null); return; }
      setActionError("Still couldn't reach the opponent. Check your connection and try again.");
      setTimeout(() => setActionError(null), 6000);
      return;
    }
    const snap = await getDoc(doc(db, "matches", gameId));
    if (snap.exists()) {
      const g = snap.data();
      setGameState((prev) => (!prev || g.version >= prev.version ? g : prev));
    }
  }

  function handleAction(action, actingIdx = myIdx) {
    if (!gameState || gameState.winner !== null) return;
    try {
      const state = JSON.parse(JSON.stringify(gameState));
      const me = state.players[actingIdx];
      const enemyIdx = actingIdx === 0 ? 1 : 0;

      if (action.type === "playCard") {
        const cardId = me.hand[action.handIdx];
        const c = findCard(cardId);
        if (c.cost > me.mana) return;
        if (c.type === "minion" && me.board.length >= 6) return;
        me.hand.splice(action.handIdx, 1);
        me.mana -= c.cost;
        let playedMinion = null;
        if (c.type === "minion") {
          playedMinion = makeMinionInstance(cardId, c.keywords.includes("Charge"));
          me.board.push(playedMinion);
        }
        log(state, `${me.hero} plays ${c.name}.`);
        if (c.effect) {
          applyEffects(state, c.effect, actingIdx, actingIdx, action.chosen ? { uid: action.chosen.uid, type: action.chosen.type, playerIdx: action.chosen.playerIdx } : null, true, playedMinion);
        }
        removeDeadMinions(state);
        checkWin(state);
      } else if (action.type === "power") {
        const pw = HERO_POWERS[me.hero];
        if (me.powerUsed || me.mana < pw.cost) return;
        me.mana -= pw.cost;
        me.powerUsed = true;
        log(state, `${me.hero} uses ${pw.name}.`);
        if (me.hero === "Wanderer") drawCard(state, actingIdx);
        else if (me.hero === "Prepper") me.armor += 2;
        else if (me.hero === "Bandit") dealDamageToPlayer(state, enemyIdx, 2);
        else if (me.hero === "Cyborg") { healPlayer(state, actingIdx, 1); me.armor += 1; }
        else if (me.hero === "Mutant" && action.chosen) {
          const m = me.board.find((x) => x.uid === action.chosen.uid);
          if (m) { m.atk += 1; m.hp += 1; m.maxHp += 1; }
        } else if (me.hero === "Scientist" && action.chosen) {
          if (action.chosen.type === "hero") dealDamageToPlayer(state, action.chosen.playerIdx, 1);
          else {
            const owner = state.players[action.chosen.playerIdx];
            const m = owner.board.find((x) => x.uid === action.chosen.uid);
            if (m) damageMinion(state, m, 1, action.chosen.playerIdx);
          }
        }
        removeDeadMinions(state);
        checkWin(state);
      } else if (action.type === "attack") {
        const atk = me.board.find((x) => x.uid === action.attackerUid);
        if (!atk || !atk.canAttack) return;
        atk.canAttack = false;
        const enemy = state.players[enemyIdx];
        if (action.target.type === "hero") {
          dealDamageToPlayer(state, enemyIdx, atk.atk);
          log(state, `${atk.name} attacks ${enemy.hero} for ${atk.atk}.`);
        } else {
          const def = enemy.board.find((x) => x.uid === action.target.uid);
          if (!def) return;
          log(state, `${atk.name} clashes with ${def.name}.`);
          damageMinion(state, def, atk.atk, enemyIdx);
          damageMinion(state, atk, def.atk, actingIdx);
        }
        const atkCardDef = atk.cardId ? findCard(atk.cardId) : null;
        if (atkCardDef && atkCardDef.onAttack) applyEffects(state, atkCardDef.onAttack, actingIdx, actingIdx, null);
        removeDeadMinions(state);
        checkWin(state);
      } else if (action.type === "endTurn") {
        state.turn = enemyIdx;
        startTurn(state);
      }
      pushState(state);
    } catch (e) {
      console.error("Action failed:", e);
      setActionError("Something went wrong with that move — the game state was not changed. You can keep playing.");
      setTimeout(() => setActionError(null), 3500);
    }
  }

  async function concede() {
    const state = JSON.parse(JSON.stringify(gameState));
    state.winner = myIdx === 0 ? 1 : 0;
    log(state, `${state.players[myIdx].hero} concedes.`);
    await pushState(state);
    if (matchListenerRef.current) { matchListenerRef.current(); matchListenerRef.current = null; }
    setScreen("select");
    setGameState(null);
    setGameId(null);
    setMyIdx(null);
    setHero(null);
    setIsCpuMatch(false);
  }

  // Leave a game that's already over (no concede/forfeit involved, just navigation).
  function returnToMenu() {
    if (matchListenerRef.current) { matchListenerRef.current(); matchListenerRef.current = null; }
    setScreen("select");
    setGameState(null);
    setGameId(null);
    setMyIdx(null);
    setHero(null);
    setIsCpuMatch(false);
  }

  if (authLoading) {
    return <div style={{ fontFamily: FONT, padding: 20 }}>Loading...</div>;
  }

  if (!user) {
    return (
      <div style={{ fontFamily: FONT, padding: 20, textAlign: "center", maxWidth: 400, margin: "40px auto" }}>
        <h1 style={{ fontSize: 28, fontFamily: FONT, fontWeight: 700, letterSpacing: 2, borderBottom: "2px solid #000", paddingBottom: 10 }}>ATOMIC SIX</h1>
        <p style={{ fontSize: 13, color: "#333", marginTop: 10 }}>Sign in to play.</p>
        <button
          onClick={signInWithGoogle}
          style={{ marginTop: 16, padding: "10px 18px", fontFamily: FONT, fontSize: 14, fontWeight: 700, border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}
        >
          Continue with Google
        </button>
      </div>
    );
  }

  return (
    <div style={{ minHeight: "100%", background: "#fff", color: "#111" }}>
      <style>{GLOBAL_STYLE}</style>
      <div style={{ maxWidth: 640, margin: "0 auto", padding: "8px 20px 0", display: "flex", justifyContent: "flex-end", fontFamily: FONT, fontSize: 11, color: "#555" }}>
        {user.displayName} — <button onClick={signOutUser} style={{ fontFamily: FONT, fontSize: 11, border: "none", background: "none", color: "#555", textDecoration: "underline", cursor: "pointer", marginLeft: 4 }}>Sign out</button>
      </div>
      {screenNotice && (
        <div style={{ maxWidth: 640, margin: "10px auto 0", fontFamily: FONT, fontSize: 12, background: "#fff3f2", border: "1px solid #c0392b", color: "#8a1f14", padding: "6px 10px", borderRadius: 4, textAlign: "center" }}>
          {screenNotice}
        </div>
      )}
      {screen === "select" && <HeroSelectScreen onPick={startSearch} onBuildDeck={openDeckBuilder} onPlayCpu={startCpuMatch} onShowLeaderboard={() => setScreen("leaderboard")} myProfile={myProfile} customDecks={customDecks} />}
      {screen === "leaderboard" && <LeaderboardScreen onBack={() => setScreen("select")} />}
      {screen === "deckbuilder" && <DeckBuilderScreen hero={deckBuilderHero} initialDeck={customDecks[deckBuilderHero] || null} onSave={(deck) => saveCustomDeck(deckBuilderHero, deck)} onCancel={() => setScreen("select")} />}
      {screen === "searching" && <SearchingScreen hero={hero} onCancel={cancelSearch} />}
      {screen === "game" && gameState && <GameScreen state={gameState} myIdx={myIdx} onAction={handleAction} onConcede={concede} actionError={actionError} onSync={manualSync} onBackToMenu={returnToMenu} />}
    </div>
  );
}
